/**
 * The free composer: a 52px pill with a text field and circular controls,
 * plus the thin status row beneath it.
 *
 * It matches the proportions of the Pro composer on purpose, so a starter
 * looks like it belongs to the same product — the fixed-height pill, 8px
 * padding with 36px circles sitting flush inside it, and the 10px gap rhythm
 * across the row. What it deliberately does NOT carry is the paid work in
 * `composer`: the liquid-glass surfaces behind the controls, the model and
 * effort menus, the attachment plugin panel, and the voice equalizer. Those
 * are the reason someone buys that component, so this one leaves the slots
 * present but plain.
 *
 * The status row shows what is actually true of the running app — which
 * provider answered, which model, how many messages are in the thread —
 * rather than decorative chrome, so it stays honest in a deployed starter.
 */

export interface AgentComposerProps {
  value: string;
  onValueChange: (value: string) => void;
  onSubmit: () => void;
  onStop: () => void;
  busy: boolean;
  /** Model id reported by the runtime, e.g. "openai/gpt-5-nano". */
  model?: string | null;
  provider?: string | null;
  messageCount: number;
  className?: string;
}

export function AgentComposer({
  value,
  onValueChange,
  onSubmit,
  onStop,
  busy,
  model,
  provider,
  messageCount,
  className,
}: AgentComposerProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    onSubmit();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      onSubmit();
    }
  };

  return (
    <div className={cx("flex w-full flex-col gap-2.5", className)}>
      {/* radius omitted: ComposerLoader defaults to a full pill, matching the form. */}
      <ComposerLoader active={busy}>
        {/* The pill sits one step lighter than the chat surface behind it in
            both themes (white on neutral-100 in light, neutral-800 on
            neutral-900 in dark), so a single token works without a dark
            override. Its controls then step back down to secondary. */}
        <form
          onSubmit={submit}
          className={cx(
            "flex h-[52px] w-full items-center gap-2.5 rounded-full p-2",
            // ComposerLoader paints its own pill surface and runs the light
            // behind its children, so an opaque form would cover the light
            // entirely. While busy the form steps aside and lets it show.
            busy ? "bg-transparent" : "bg-background-primary-default shadow-xs",
          )}
        >
          {/* Attachment slot. Plain on purpose — the plugin panel behind this
              button in the Pro composer is part of what that component sells. */}
          {/* Shares the Pro composer's add-button tokens so the two read as the
              same control. They resolve one step lighter than the pill in dark
              and one step darker in light, which is why a single pair works for
              both themes without a dark: override. */}
          <button
            type="button"
            aria-label="Add attachment"
            className="flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full bg-ai-chat-composer-add-background text-foreground-icon-primary transition-colors duration-150 ease hover:bg-ai-chat-composer-add-hover-background"
          >
            <RiAttachment2 className="size-5" aria-hidden />
          </button>

          <label className="sr-only" htmlFor="agent-composer-input">
            Message
          </label>
          <input
            id="agent-composer-input"
            ref={inputRef}
            type="text"
            value={value}
            onChange={(event) => onValueChange(event.target.value)}
            onKeyDown={onKeyDown}
            placeholder="Ask me anything"
            autoComplete="off"
            className="h-5 min-w-0 flex-1 bg-transparent text-body-regular text-text-primary caret-text-primary outline-none placeholder:text-text-tertiary"
          />

          {model ? (
            <span
              // Static where the Pro composer puts its model picker: the model
              // is set by an env var, so there is nothing to switch at runtime.
              className="flex h-8 shrink-0 items-center gap-1 rounded-xl py-1.5 pr-2 pl-2 text-body-2-medium text-text-secondary"
              title={`Answering with ${model}`}
            >
              <RiSparklingLine className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />
              <span className="hidden max-w-[13ch] truncate sm:inline">{shortModel(model)}</span>
            </span>
          ) : null}

          <div className="flex shrink-0 items-center gap-2 pl-1.5">
            {busy ? (
              <button
                type="button"
                onClick={onStop}
                aria-label="Stop generating"
                className="flex size-9 cursor-pointer items-center justify-center rounded-full bg-background-secondary-default text-foreground-icon-secondary transition-colors hover:bg-background-secondary-hover"
              >
                <RiStopFill className="size-5" aria-hidden />
              </button>
            ) : (
              <button
                type="submit"
                aria-label="Send message"
                disabled={value.trim().length === 0}
                className="flex size-9 cursor-pointer items-center justify-center rounded-full bg-button-primary text-white transition-opacity disabled:cursor-not-allowed disabled:opacity-40"
              >
                <RiArrowUpLine className="size-5" aria-hidden />
              </button>
            )}
          </div>
        </form>
      </ComposerLoader>

      <div className="flex h-[26px] w-full items-center justify-between">
        <div className="flex items-center gap-3">
          <StatusItem icon={RiInfinityLine} label={provider ?? "Not configured"} />
        </div>
        <div className="flex items-center gap-3">
          <StatusItem
            icon={RiSparklingLine}
            label={messageCount === 0 ? "New chat" : `${messageCount} messages`}
          />
        </div>
      </div>
    </div>
  );
}

function StatusItem({
  icon: Icon,
  label,
}: {
  icon: typeof RiInfinityLine;
  label: string;
}) {
  return (
    <span className="flex items-center gap-1">
      <Icon className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden />
      <span className="whitespace-nowrap text-body-2-medium text-text-secondary">{label}</span>
    </span>
  );
}

/** "openai/gpt-5-nano" reads better in a 13ch slot as "gpt-5-nano". */
function shortModel(model: string) {
  const slash = model.lastIndexOf("/");
  return slash === -1 ? model : model.slice(slash + 1);
}

/**
 * What the chat says when there is no model behind it.
 *
 * Demo mode exists so a fresh deploy can be tried before a key is added: the
 * screen, the streaming, the history all behave as they do with a model, and
 * only the words are canned. Each answer says so, quietly, so nobody mistakes
 * it for a model's.
 */

type DemoAnswer = { match: RegExp; reply: string };

const ANSWERS: DemoAnswer[] = [
  {
    match: /starter|what (is|does) this|about this app|zeus/i,
    reply:
      "This is the Zeus chat starter: a Next.js app with a streaming chat, a dashboard, an inbox and sign-in screens, all built from Zeus's free components and installed as source you own. Right now I'm in demo mode, so this answer is canned. Add AI_API_KEY in your hosting project settings, redeploy, and the same chat talks to a real model.",
  },
  {
    match: /product update|announcement|release notes|changelog/i,
    reply:
      "Here's a product update in three sentences. This release adds a dashboard with revenue and orders charts, an inbox, and sign-in and sign-up screens, all built from the same free components as the chat. Every page installs as source, so nothing is locked behind a package. It deploys to your host in a click and runs on your own model key. (Demo mode: canned answer. Add AI_API_KEY for a real one.)",
  },
  {
    match: /names?\b.*\b(app|product|scheduling|startup|company)|name ideas|suggest.*names/i,
    reply:
      "Five names for a scheduling app: Slotwise, Tidemark, Cadence, Dayline, and Meridian. Slotwise says what it does, Cadence and Meridian carry a rhythm, Tidemark and Dayline feel like calendars without saying so. (Demo mode: canned answer. With a key, I'd tailor these to your product.)",
  },
  {
    match: /key|api|openrouter|openai|anthropic|provider|model/i,
    reply:
      "To connect a real model, add one environment variable, AI_API_KEY, in your hosting project (Settings, then Environment Variables) and redeploy. The provider is read from the key itself: Any supported model provider works. Set CHAT_MODEL if you want a specific model. Until then I'm in demo mode, answering from a short script.",
  },
  {
    match: /hello|hi\b|hey|good (morning|afternoon|evening)/i,
    reply:
      "Hello. I'm the starter's demo assistant, answering from a short script until a model key is added. Try asking what this starter does, or how to connect a key.",
  },
];

const FALLBACK =
  "I'm in demo mode, so I can only answer from a short script, and that question isn't in it. Add AI_API_KEY in your hosting project settings and redeploy, and this same chat will answer properly. Meanwhile, try: what does this starter do, or how do I connect a key.";

export function pickDemoAnswer(prompt: string): string {
  return ANSWERS.find((answer) => answer.match.test(prompt))?.reply ?? FALLBACK;
}

import type { ChatTransport, UIMessage, UIMessageChunk } from "ai";

import { pickDemoAnswer } from "./demo-answers";

/** A beat before the first word, so the thinking indicator reads as thinking. */
const THINK_MS = 700;
/** Per word. Slightly faster than a model, since there is nothing to wait for. */
const WORD_MS = 28;

const wait = (ms: number, signal?: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    });
  });

function lastUserText(messages: UIMessage[]): string {
  const last = [...messages].reverse().find((message) => message.role === "user");
  return (
    last?.parts
      .filter((part): part is { type: "text"; text: string } => part.type === "text")
      .map((part) => part.text)
      .join("\n") ?? ""
  );
}

/**
 * The chat transport for a deploy that has no model key yet. It speaks the
 * same UI-message stream the real route does, so `useChat` cannot tell the
 * difference: the words arrive one at a time, Stop works, and the thread is
 * saved like any other. Only the words are scripted.
 */
export class DemoTransport implements ChatTransport<UIMessage> {
  async sendMessages({
    messages,
    abortSignal,
  }: {
    messages: UIMessage[];
    abortSignal: AbortSignal | undefined;
  }): Promise<ReadableStream<UIMessageChunk>> {
    const reply = pickDemoAnswer(lastUserText(messages));
    const id = `demo-${Date.now()}`;
    return new ReadableStream<UIMessageChunk>({
      async start(controller) {
        try {
          controller.enqueue({ type: "start" });
          controller.enqueue({ type: "start-step" });
          await wait(THINK_MS, abortSignal);
          controller.enqueue({ type: "text-start", id });
          const words = reply.split(/(?<=\s)/);
          for (const word of words) {
            await wait(WORD_MS, abortSignal);
            controller.enqueue({ type: "text-delta", id, delta: word });
          }
          controller.enqueue({ type: "text-end", id });
          controller.enqueue({ type: "finish-step" });
          controller.enqueue({ type: "finish" });
        } catch {
          controller.enqueue({ type: "abort" });
        } finally {
          controller.close();
        }
      },
    });
  }

  async reconnectToStream(): Promise<ReadableStream<UIMessageChunk> | null> {
    return null;
  }
}

/**
 * Holds both transports and answers per request: a send carrying
 * `body.demo` goes to the script, anything else to the real route. Nothing is
 * mutated after construction, so `useChat` keeps one instance for good.
 */
export class SwitchingTransport implements ChatTransport<UIMessage> {
  // Plain fields rather than parameter properties, so copied source compiles
  // under TypeScript's erasableSyntaxOnly (on in Vite's React template).
  private readonly live: ChatTransport<UIMessage>;
  private readonly canned: ChatTransport<UIMessage>;

  constructor(live: ChatTransport<UIMessage>, canned: ChatTransport<UIMessage>) {
    this.live = live;
    this.canned = canned;
  }

  sendMessages: ChatTransport<UIMessage>["sendMessages"] = (options) => {
    const demo = Boolean((options.body as { demo?: boolean } | undefined)?.demo);
    return (demo ? this.canned : this.live).sendMessages(options);
  };

  reconnectToStream: ChatTransport<UIMessage>["reconnectToStream"] = (options) =>
    this.live.reconnectToStream(options);
}

// @zeus-internal
import type { AgentShape } from "./agent-avatar-paths";
export function createAgentAvatarRenderer(canvas: HTMLCanvasElement): {
  update(options: {
    color: string;
    shape: AgentShape;
    emotion?: number;
    silhouette?: boolean;
  }): boolean;
  setVisible(visible: boolean): void;
  dispose(): void;
};

// @zeus-internal
import * as THREE from "three";
import { SVGLoader } from "three/addons/loaders/SVGLoader.js";
import { AGENT_SHAPE_PATHS, AGENT_SHAPE_LAYOUT, normalizeAgentShape, agentFacePaths } from "./agent-avatar-paths";
import { agentFaceColor, agentSideColor } from "./agent-colors";
import { createAvatarMotion } from "./avatar-motion";
import { subscribeAvatarFrames } from "./avatar-motion-clock";

// One offscreen renderer serves all avatar canvases, including narrow navigation items.
let renderer;
let clients = 0;
let disposeTimer;
const geometries = new Map();
function bodyGeometry(shape) {
  const key = normalizeAgentShape(shape);
  if (geometries.has(key)) return geometries.get(key);
  const data = new SVGLoader().parse(
    `<svg xmlns="http://www.w3.org/2000/svg"><path d="${AGENT_SHAPE_PATHS[key]}"/></svg>`,
  );
  const shapes = data.paths.flatMap((path) => SVGLoader.createShapes(path));
  const geometry = new THREE.ExtrudeGeometry(shapes, {
    depth: 10,
    bevelEnabled: true,
    bevelSegments: 3,
    steps: 1,
    bevelSize: 0.5,
    bevelThickness: 0.4,
    curveSegments: 24,
  });
  geometry.computeBoundingBox();
  const box = geometry.boundingBox;
  const layout = AGENT_SHAPE_LAYOUT[key] ?? {};
  const scale = (layout.extent ?? 2.6) / Math.max(box.max.x - box.min.x, box.max.y - box.min.y);
  geometry.translate(-(box.min.x + box.max.x) / 2, -(box.min.y + box.max.y) / 2, -5);
  geometry.scale(scale * (layout.width ?? 1), -scale * (layout.height ?? 1), scale);
  geometry.translate(layout.x ?? 0, layout.y ?? 0, 0);
  geometry.computeVertexNormals();
  geometries.set(key, geometry);
  return geometry;
}
function grain(material) {
  material.onBeforeCompile = (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <dithering_fragment>",
      `#include <dithering_fragment>
      float first = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898,78.233))) * 43758.5453);
      float second = fract(sin(dot(gl_FragCoord.xy + vec2(31.7,9.2), vec2(39.346,11.135))) * 27463.235);
      float noise = .5 + (first + second - 1.) * .02;
      vec3 low = 2. * gl_FragColor.rgb * noise;
      vec3 high = 1. - 2. * (1. - gl_FragColor.rgb) * (1. - noise);
      gl_FragColor.rgb = mix(low, high, step(vec3(.5), gl_FragColor.rgb));`,
    );
  };
  return material;
}
export function createAgentAvatarRenderer(canvas) {
  clearTimeout(disposeTimer);
  if (!renderer) {
    renderer = new THREE.WebGLRenderer({
      alpha: true,
      antialias: true,
      preserveDrawingBuffer: true,
    });
    renderer.setSize(256, 256, false);
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
  }
  clients++;
  const context = canvas.getContext("2d"),
    scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1.5, 1.5, 1.5, -1.5, 0.1, 20);
  camera.position.set(0, 0, 6);
  const group = new THREE.Group();
  scene.add(group);
  const front = grain(
    new THREE.MeshBasicMaterial({
      color: 0xa4dfe0,
      side: THREE.DoubleSide,
    }),
  );
  const side = grain(
    new THREE.MeshBasicMaterial({
      color: 0x448f9a,
      side: THREE.DoubleSide,
    }),
  );
  const body = new THREE.Mesh(bodyGeometry("shield"), [front, side]);
  group.add(body);
  const face = new THREE.Group();
  group.add(face);
  face.position.set(0.131, 0.0665, 0);
  face.scale.setScalar(1.095);
  let expression, renderedColor, faceColor = "#111117";
  function setExpression(emotion) {
    if (emotion === expression) return;
    expression = emotion;
    for (const child of [...face.children]) {
      face.remove(child);
      child.geometry.dispose();
      child.material.dispose();
    }
    for (const [index, path] of agentFacePaths(emotion).entries()) {
      const data = new SVGLoader().parse(
        `<svg xmlns="http://www.w3.org/2000/svg"><path d="${path.d}"${path.transform ? ` transform="${path.transform}"` : ""}/></svg>`,
      );
      const shapes = data.paths.flatMap((p) => SVGLoader.createShapes(p));
      const geometry = new THREE.ShapeGeometry(shapes, 20);
      geometry.translate(-17.5, -17.5, 0);
      geometry.scale(0.0375, -0.0375, 0.0375);
      geometry.computeBoundingBox();
      const center = geometry.boundingBox.getCenter(new THREE.Vector3());
      geometry.translate(-center.x, -center.y, -center.z);
      const material = new THREE.MeshBasicMaterial({
        color: faceColor,
        side: THREE.DoubleSide,
        opacity: path.opacity ?? 1,
        transparent: path.opacity !== undefined,
      });
      const mesh = new THREE.Mesh(geometry, material);
      // Small picker marks have a larger optical size than dimensional marks.
      // Keep their shared layout spacing while scaling each feature around its centre.
      const pivot = new THREE.Vector3(-0.5 * 0.047, 0.5 * 0.047, 0);
      mesh.position.copy(center).multiplyScalar(0.047 / 0.0375)
        .sub(pivot).applyAxisAngle(new THREE.Vector3(0, 0, 1), 7 * Math.PI / 180).add(pivot);
      mesh.userData.blink = index < 2;
      face.add(mesh);
    }
  }
  group.rotation.set(0.180625, -0.328125, 0.095625);
  group.scale.setScalar(0.9875);
  let disposed = false, width = 0, pose;
  const sampleMotion = createAvatarMotion(Math.floor(Math.random() * 4294967296));
  function draw() {
    if (disposed || !context || !width) return false;
    if (pose) {
      const { lookX, lookY } = pose;
      group.position.y = pose.bob;
      group.rotation.set(-0.072 + lookY * 0.2, -0.25 + lookX * (lookX < 0 ? 0.3 : 0.85), pose.roll);
      face.position.x = 0.146 + lookX * (lookX < 0 ? 0.48 : 0.38);
      face.position.y = 0.1315 - lookY * 0.41;
      face.scale.setScalar(1.1 * (1 - 0.13 * Math.min(1.4, Math.hypot(lookX, lookY))));
    } else {
      group.position.y = 0;
      group.rotation.set(0.180625, -0.328125, 0.095625);
      face.position.x = 0.131;
      face.position.y = 0.0665;
      face.scale.setScalar(1.095);
    }
    for (const child of face.children) child.scale.y = child.userData.blink ? pose?.blink ?? 1 : 1;
    renderer.setViewport(0, 0, width, width);
    renderer.clear();
    renderer.render(scene, camera);
    context.clearRect(0, 0, width, width);
    context.drawImage(renderer.domElement, 0, 256 - width, width, width, 0, 0, width, width);
    return true;
  }
  const clock = subscribeAvatarFrames(elapsed => {
    pose = sampleMotion(elapsed);
    draw();
  });
  return {
    update({ color, shape, emotion = 0, silhouette = false }) {
      if (disposed || !context) return false;
      width = Math.max(0, Math.min(256, canvas.clientWidth));
      if (canvas.width !== width || canvas.height !== width) {
        canvas.width = width;
        canvas.height = width;
      }
      body.geometry = bodyGeometry(shape);
      face.position.z = body.geometry.boundingBox.max.z + 0.01;
      if (renderedColor !== color) {
        renderedColor = color;
        front.color.set(color);
        side.color.set(agentSideColor(color));
        faceColor = agentFaceColor(color);
        for (const child of face.children) child.material.color.set(faceColor);
      }
      setExpression(emotion);
      face.visible = !silhouette;
      clock.setEnabled(!silhouette && width > 0);
      if (silhouette) pose = undefined;
      else if (!clock.reduced && !pose) pose = sampleMotion(clock.elapsed);
      return draw();
    },
    setVisible(visible) { clock.setVisible(visible); },
    dispose() {
      if (disposed) return;
      disposed = true;
      clock.dispose();
      clients--;
      for (const child of face.children) {
        child.geometry.dispose();
        child.material.dispose();
      }
      front.dispose();
      side.dispose();

      if (!clients)
        disposeTimer = setTimeout(() => {
          if (clients) return;
          renderer?.dispose();
          renderer = undefined;
          for (const geometry of geometries.values()) geometry.dispose();
          geometries.clear();
        }, 0);
    },
  };
