"use client";
import { useEffect, useId, useRef, useState } from "react";
import { cx } from "@/lib/cx";
import { parseColor } from "react-aria-components";
import { createAgentAvatarRenderer } from "./agent-avatar-engine.jsx";
import { agentFaceColor } from "./agent-colors";
import {
  AGENT_SHAPE_PATHS,
  agentFacePaths,
  normalizeAgentShape,
  type AgentShape,
} from "./agent-avatar-paths";
export interface AgentAvatarProps {
  color?: string;
  shape?: AgentShape;
  emotion?: number;
  silhouette?: boolean;
  faceOnly?: boolean;
  className?: string;
}
/** One avatar surface for navigation, conversation labels and the appearance editor. */
export function AgentAvatar({
  color = "#a4dfe0",
  shape = "robot",
  emotion = 0,
  silhouette = false,
  faceOnly = false,
  className,
}: AgentAvatarProps) {
  const id = useId().replaceAll(":", "");
  const canvas = useRef<HTMLCanvasElement>(null);
  const configuration = useRef({ color, shape, emotion, silhouette });
  configuration.current = { color, shape, emotion, silhouette };
  const redraw = useRef<() => void>(() => {});
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (faceOnly || !canvas.current) { setReady(false);return; }
    let renderer: ReturnType<typeof createAgentAvatarRenderer> | undefined;
    let observer: ResizeObserver | undefined;
    let intersection: IntersectionObserver | undefined;
    let visibility: MutationObserver | undefined;
    let intersecting = true;
    const ancestors: HTMLElement[] = [];
    const element = canvas.current;
    const refreshVisibility = () => {
      let painted = true;
      if (typeof element.checkVisibility === "function") {
        painted = element.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true });
      } else {
        for (let node: HTMLElement | null = element; node; node = node.parentElement) {
          const style = getComputedStyle(node);
          if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") {
            painted = false;break;
          }
        }
      }
      renderer?.setVisible(intersecting && painted);
    };
    const animationEnd = (event: Event) => {
      if (event.target === event.currentTarget) refreshVisibility();
    };
    const draw = () => {
      const current = configuration.current;
      try {
        element.style.color = current.color;
        refreshVisibility();
        setReady(renderer?.update({
          ...current,
          color: parseColor(getComputedStyle(element).color).toString("hex"),
        }) ?? false);
      } catch { setReady(false); }
    };
    try {
      renderer = createAgentAvatarRenderer(element);
      redraw.current = draw;
      draw();
      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(draw);
        observer.observe(element);
      }
      if (typeof IntersectionObserver !== "undefined") {
        intersection = new IntersectionObserver(entries => {
          for (const entry of entries) if (entry.target === element) {
            intersecting = entry.isIntersecting;
            refreshVisibility();
          }
        });
        intersection.observe(element);
      }
      visibility = new MutationObserver(() => {
        if (!configuration.current.silhouette) refreshVisibility();
      });
      for (let parent = element.parentElement; parent; parent = parent.parentElement) {
        ancestors.push(parent);
        visibility.observe(parent, { attributes: true, attributeFilter: ["class", "style", "hidden"] });
        parent.addEventListener("animationend", animationEnd);
        parent.addEventListener("transitionend", animationEnd);
      }
    } catch {
      setReady(false);
    }
    return () => {
      observer?.disconnect();
      intersection?.disconnect();
      visibility?.disconnect();
      for (const parent of ancestors) {
        parent.removeEventListener("animationend", animationEnd);
        parent.removeEventListener("transitionend", animationEnd);
      }
      if (redraw.current === draw) redraw.current = () => {};
      renderer?.dispose();
    };
  }, [faceOnly]);
  useEffect(() => redraw.current(), [color, shape, emotion, silhouette]);
  return (
    <span
      aria-hidden="true"
      className={cx("relative inline-block size-10 shrink-0 align-middle", className)}
    >
      <svg
        viewBox={faceOnly ? "0 0 34 34" : "0 0 68 68"}
        className={cx(
          "absolute inset-0 size-full overflow-visible",
          ready && !faceOnly && "invisible",
        )}
      >
        {!faceOnly && (
          <>
            <defs>
              <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
                <stop stopColor={color} />
                <stop offset="1" stopColor={color} stopOpacity=".85" />
              </linearGradient>
            </defs>
            <path
              d={AGENT_SHAPE_PATHS[normalizeAgentShape(shape)]}
              fill={color}
              transform="translate(2 0)"
              style={{ filter: "brightness(.65)" }}
            />
            <path d={AGENT_SHAPE_PATHS[normalizeAgentShape(shape)]} fill={`url(#${id})`} />
          </>
        )}
        {!silhouette && (
          <g
            transform={
              faceOnly ? "rotate(-7 17 17)" : "translate(14 14) rotate(-7 17 17) scale(1.1)"
            }
            fill={agentFaceColor(color)}
            stroke={agentFaceColor(color)}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {agentFacePaths(emotion).map((path, i) => (
              <path key={i} d={path.d} opacity={path.opacity} transform={path.transform} stroke="none" />
            ))}
          </g>
        )}
      </svg>
      {!faceOnly && (
        <canvas ref={canvas} className={cx("absolute inset-0 size-full", !ready && "invisible")} />
      )}
    </span>
  );
}

// @zeus-internal
import { parseColor } from "react-aria-components";

/** Independently fitted side tone from the rendered colour samples. */
export function agentSideColor(value: string): string {
  const color = parseColor(value).toFormat("hsl");
  return color
    .withChannelValue("hue", (color.getChannelValue("hue") + 5.5) % 360)
    .withChannelValue("saturation", color.getChannelValue("saturation") * 0.85)
    .withChannelValue("lightness", Math.max(0, color.getChannelValue("lightness") - 28))
    .toString("hex");
}

export function agentFaceColor(value: string): string {
  try {
    return parseColor(value).toFormat("hsl").getChannelValue("lightness") < 35
      ? "#fbfaf8"
      : "#111117";
  } catch {
    // CSS variables resolve on the canvas before its dimensional renderer draws.
    return "#111117";
  }
}

// @zeus-internal
interface Client {
  draw: (elapsed: number) => void;
  enabled: boolean;
  visible: boolean;
  elapsed: number;
}
const clients = new Set<Client>();
let frame = 0, previous: number | undefined, lastPaint: number | undefined;
let reduced: MediaQueryList | undefined;
const runnable = () => !reduced?.matches && !document.hidden && [...clients].some(c => c.enabled && c.visible);
function synchronize() {
  if (!runnable()) {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;previous = undefined;lastPaint = undefined;
  } else if (!frame) frame = requestAnimationFrame(tick);
}
function tick(now: number) {
  frame = 0;
  if (!runnable()) { synchronize();return; }
  if (lastPaint === undefined || now - lastPaint >= 1000 / 30 - 0.5) {
    const delta = previous === undefined ? 0 : Math.max(0, now - previous);
    previous = now;
    lastPaint = now;
    for (const client of clients) if (client.enabled && client.visible) {
      client.elapsed += delta;
      client.draw(client.elapsed);
    }
  }
  synchronize();
}

/** A single paced RAF and preference subscription serve all dimensional avatars. */
export function subscribeAvatarFrames(draw: (elapsed: number) => void) {
  if (!clients.size) {
    reduced = matchMedia("(prefers-reduced-motion: reduce)");
    reduced.addEventListener("change", synchronize);
    document.addEventListener("visibilitychange", synchronize);
  }
  const client: Client = { draw, enabled: false, visible: true, elapsed: 0 };
  clients.add(client);
  let disposed = false;
  return {
    get elapsed() { return client.elapsed; },
    get reduced() { return reduced?.matches ?? false; },
    setEnabled(enabled: boolean) { if (!disposed) { client.enabled = enabled;synchronize(); } },
    setVisible(visible: boolean) { if (!disposed) { client.visible = visible;synchronize(); } },
    dispose() {
      if (disposed) return;
      disposed = true;clients.delete(client);synchronize();
      if (!clients.size) {
        reduced?.removeEventListener("change", synchronize);
        document.removeEventListener("visibilitychange", synchronize);
        reduced = undefined;
      }
    },
  };
}

// @zeus-internal
export interface AvatarMotionFrame {
  lookX: number;
  lookY: number;
  blink: number;
  bob: number;
  roll: number;
}
const targets = [
  [-24, -19], [-1, -5], [-4, -13], [6, -11], [2, -4], [12, -16],
  [14, 15], [-4, 11], [-4, 16], [-6, 12], [-14, 9], [16, -23],
  [11, -17], [3, 0], [-2, 4], [7, 1],
] as const;
const gazeIntervals = [2000, 2500, 1000, 2700, 1800, 1400, 1100, 1500, 900, 1700, 1300];
const blinkIntervals = [2283, 2383, 4050, 5166, 6633, 7016, 7399];
const blinkDurations = [110, 142, 164, 188, 194, 198];
const random = (seed: number) => () => {
  seed |= 0;
  seed = seed + 0x6d2b79f5 | 0;
  let value = Math.imul(seed ^ seed >>> 15, 1 | seed);
  value ^= value + Math.imul(value ^ value >>> 7, 61 | value);
  return ((value ^ value >>> 14) >>> 0) / 4294967296;
};
const smootherstep = (value: number) => {
  const t = Math.max(0, Math.min(1, value));
  return t * t * t * (t * (6 * t - 15) + 10);
};

/** Independent idle motion calibrated from rendered timing and pose samples. */
export function createAvatarMotion(seed: number) {
  let gazeRandom = random(seed ^ 0x21f0aaad), blinkRandom = random(seed ^ 0x735a2d97);
  const phase = random(seed ^ 0x4ac1709b)() * Math.PI * 2;
  let previous = -1, gazeStart = 0, nextGaze = 0, targetIndex = -1;
  let from = [0, 0], to = [0, 0];
  let blinkStart = 0, blinkDuration = 0;
  const pick = (values: readonly number[], next: () => number) => values[Math.floor(next() * values.length)];
  const reset = () => {
    gazeRandom = random(seed ^ 0x21f0aaad);
    blinkRandom = random(seed ^ 0x735a2d97);
    previous = -1;gazeStart = 0;targetIndex = -1;from = [0, 0];to = [0, 0];
    nextGaze = pick(gazeIntervals, gazeRandom);
    blinkStart = pick(blinkIntervals, blinkRandom);
    blinkDuration = pick(blinkDurations, blinkRandom);
  };
  reset();
  return (elapsed: number): AvatarMotionFrame => {
    const time = Math.max(0, elapsed);
    if (time < previous) reset();
    previous = time;
    while (time >= nextGaze) {
      from = [...to];
      const index = Math.floor(gazeRandom() * targets.length);
      targetIndex = index === targetIndex ? (index + 1) % targets.length : index;
      const target = targets[targetIndex];
      to = [(target[0] + 3) / 30, (target[1] + 9) / 25];
      gazeStart = nextGaze;
      nextGaze += pick(gazeIntervals, gazeRandom);
    }
    while (time >= blinkStart + blinkDuration) {
      blinkStart += pick(blinkIntervals, blinkRandom);
      blinkDuration = pick(blinkDurations, blinkRandom);
    }
    const progress = smootherstep((time - gazeStart) / 895);
    const blinkProgress = (time - blinkStart) / blinkDuration;
    const wave = Math.sin(time / 8015 * Math.PI * 2 + phase);
    return {
      lookX: from[0] + (to[0] - from[0]) * progress,
      lookY: from[1] + (to[1] - from[1]) * progress,
      blink: blinkProgress < 0 || blinkProgress > 1 ? 1 : Math.max(0.1, 1 - Math.sin(Math.PI * blinkProgress) ** 1.3),
      bob: wave * 0.01508,
      roll: 0.055 + wave * 0.028,
    };
  };
}

